#!/bin/bash

# Wires the Zipline plugin into Omarchy. Safe to run again at any time: every
# change is either a generated file or a marked block that is replaced, never
# duplicated. Backups of edited user files are written next to them.
#
#   ./install.sh                 plugin + CLI + keybindings + menu entries
#   ./install.sh --no-bindings   skip the Hyprland keybindings
#   ./install.sh --no-menu       skip the Omarchy menu entries
#   ./install.sh --no-bar        don't add the widget to the bar

set -euo pipefail

PLUGIN_ID="io.github.cempack.zipline"
SRC_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)
PLUGINS_DIR="$HOME/.config/omarchy/plugins"
PLUGIN_DIR="$PLUGINS_DIR/$PLUGIN_ID"
HYPR_DIR="$HOME/.config/hypr"
BINDINGS_FILE="$HYPR_DIR/bindings.lua"
ZIPLINE_LUA="$HYPR_DIR/zipline.lua"
MENU_FILE="$HOME/.config/omarchy/extensions/omarchy-menu.jsonc"
BIN_LINK="$HOME/.local/bin/omarchy-zipline"
CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/omarchy-zipline"
MARK_BEGIN="omarchy-zipline >>>"
MARK_END="<<< omarchy-zipline"

WANT_BINDINGS=1
WANT_MENU=1
WANT_BAR=1

for arg in "$@"; do
  case $arg in
    --no-bindings) WANT_BINDINGS=0 ;;
    --no-menu) WANT_MENU=0 ;;
    --no-bar) WANT_BAR=0 ;;
    -h | --help)
      sed -n '3,12p' "$0" | sed 's/^# \{0,1\}//'
      exit 0
      ;;
    *)
      echo "install.sh: unknown option: $arg" >&2
      exit 1
      ;;
  esac
done

say() { printf '  %s\n' "$*"; }
have() { command -v "$1" >/dev/null 2>&1; }

backup() {
  [[ -f $1 ]] && cp -p "$1" "$1.bak.$(date +%s)"
  return 0
}

for dep in curl jq wl-copy wl-paste file; do
  have "$dep" || {
    echo "install.sh: missing dependency: $dep" >&2
    exit 1
  }
done

echo "Installing Zipline for Omarchy"

# 1. Plugin files. `omarchy plugin add` clones straight into $PLUGIN_DIR; a
#    checkout elsewhere is copied there (never over an existing git checkout).
if [[ $SRC_DIR != "$(cd "$PLUGIN_DIR" 2>/dev/null && pwd -P)" ]]; then
  if [[ -d $PLUGIN_DIR/.git ]]; then
    say "Plugin already installed from git at $PLUGIN_DIR (update with: omarchy plugin update $PLUGIN_ID)"
  else
    mkdir -p "$PLUGIN_DIR"
    tar -C "$SRC_DIR" --exclude=.git --exclude=test -cf - . | tar -C "$PLUGIN_DIR" -xf -
    say "Copied plugin to $PLUGIN_DIR"
  fi
fi
HELPER="$PLUGIN_DIR/bin/omarchy-zipline"
chmod +x "$HELPER"

if have omarchy-shell && omarchy-shell shell ping >/dev/null 2>&1; then
  omarchy-shell shell rescanPlugins >/dev/null 2>&1 || true
  if ((WANT_BAR)) && ! omarchy-shell shell listPlugins 2>/dev/null |
    jq -e --arg id "$PLUGIN_ID" 'any(.[]; .id == $id and .enabled == true)' >/dev/null 2>&1; then
    if omarchy plugin enable "$PLUGIN_ID" --section right >/dev/null 2>&1; then
      say "Added the Zipline icon to the right of the bar"
    else
      say "Could not enable the bar widget; run: omarchy plugin enable $PLUGIN_ID --section right"
    fi
  fi
fi

# 2. CLI on PATH.
mkdir -p "$(dirname "$BIN_LINK")"
if [[ -e $BIN_LINK && ! -L $BIN_LINK ]]; then
  mv "$BIN_LINK" "$BIN_LINK.bak.$(date +%s)"
fi
ln -sfn "$HELPER" "$BIN_LINK"
say "Linked $BIN_LINK"

# 3. Config placeholder (no secrets written here).
mkdir -p "$CONFIG_DIR"
chmod 700 "$CONFIG_DIR"
if [[ ! -f $CONFIG_DIR/config ]]; then
  (
    umask 077
    cat >"$CONFIG_DIR/config" <<'EOF'
# omarchy-zipline configuration (keep this file private: chmod 600)
# Fill these in, or run: omarchy-zipline setup
ZIPLINE_URL=
ZIPLINE_TOKEN=
EOF
  )
  say "Created $CONFIG_DIR/config (mode 600)"
fi
chmod 600 "$CONFIG_DIR/config"

# 4. Hyprland keybindings in their own file, loaded from bindings.lua.
if ((WANT_BINDINGS)) && [[ -f $BINDINGS_FILE ]]; then
  cat >"$ZIPLINE_LUA" <<EOF
-- Generated by omarchy-zipline's install.sh. Rerunning the installer rewrites
-- this file; remove it with uninstall.sh. To change keys, edit them here and
-- run install.sh with --no-bindings afterwards so your edits are kept.

local zipline = o.shell_quote([[$HELPER]])

o.bind("SHIFT + PRINT", "Upload screenshot to Zipline", zipline .. " screenshot")
o.bind("CTRL + SHIFT + PRINT", "Upload full-screen screenshot to Zipline", zipline .. " screenshot fullscreen")
o.bind("ALT + SHIFT + PRINT", "Upload last screen recording to Zipline", zipline .. " recording")
o.bind("SUPER + CTRL + U", "Upload clipboard to Zipline", zipline .. " clipboard")
o.bind("SUPER + CTRL + SHIFT + U", "Zipline panel", "omarchy-shell $PLUGIN_ID toggle || omarchy-menu toggle trigger.capture.zipline")
EOF
  if ! grep -q "$MARK_BEGIN" "$BINDINGS_FILE"; then
    backup "$BINDINGS_FILE"
    cat >>"$BINDINGS_FILE" <<EOF

-- $MARK_BEGIN (managed by omarchy-zipline; uninstall.sh removes this block)
require("default.hypr.require_optional").module("hypr.zipline")
-- $MARK_END
EOF
  fi
  say "Keybindings: Shift+Print, Ctrl+Shift+Print, Alt+Shift+Print, Super+Ctrl+U, Super+Ctrl+Shift+U"

  if have omarchy && omarchy menu keybindings --print >/dev/null 2>&1; then
    # Warn about keys the user already uses for something else.
    taken=$(omarchy menu keybindings --print 2>/dev/null | grep -vi zipline |
      grep -E '^(SHIFT \+ PRINT|CTRL SHIFT \+ PRINT|SHIFT CTRL \+ PRINT|ALT SHIFT \+ PRINT|SHIFT ALT \+ PRINT|SUPER CTRL \+ U|SUPER CTRL SHIFT \+ U|SUPER SHIFT CTRL \+ U) ' || true)
    if [[ -n $taken ]]; then
      say "Heads up, these keys are also bound elsewhere:"
      printf '%s\n' "$taken" | sed 's/^/      /'
    fi
  fi
elif ((WANT_BINDINGS)); then
  say "No $BINDINGS_FILE found; skipped keybindings (is this Omarchy 4?)"
fi

# 5. Omarchy menu entries under Capture.
if ((WANT_MENU)); then
  mkdir -p "$(dirname "$MENU_FILE")"
  [[ -f $MENU_FILE ]] || printf '{\n}\n' >"$MENU_FILE"
  backup "$MENU_FILE"
  if python3 -I - "$MENU_FILE" "$HELPER" "$MARK_BEGIN" "$MARK_END" <<'PY'; then
import json, re, shlex, sys

path, helper, begin, end = sys.argv[1:5]
text = open(path, encoding="utf-8").read()

# Drop any previous block (markers sit on their own comment lines).
text = re.sub(r"\n?[ \t]*// " + re.escape(begin) + r".*?// " + re.escape(end) + r"[^\n]*", "", text, flags=re.S)

z = shlex.quote(helper)
rows = {
    "trigger.capture.zipline": {"icon": "󰅧", "label": "Zipline", "aliases": ["zipline", "upload"]},
    "trigger.capture.zipline.region": {"icon": "󰆞", "label": "Upload screenshot", "action": z + " screenshot"},
    "trigger.capture.zipline.window": {"icon": "󰖯", "label": "Upload window", "action": z + " screenshot windows"},
    "trigger.capture.zipline.fullscreen": {"icon": "󰍹", "label": "Upload full screen", "action": z + " screenshot fullscreen"},
    "trigger.capture.zipline.recording": {"icon": "󰕧", "label": "Upload last recording", "action": z + " recording"},
    "trigger.capture.zipline.clipboard": {"icon": "󰅇", "label": "Upload clipboard", "action": z + " clipboard"},
    "trigger.capture.zipline.file": {"icon": "󰈔", "label": "Upload file", "action": z + " file"},
    "trigger.capture.zipline.shorten": {"icon": "󰌹", "label": "Shorten copied link", "action": z + " shorten"},
    "trigger.capture.zipline.last": {"icon": "󰆏", "label": "Copy last link", "action": z + " last"},
    "trigger.capture.zipline.setup": {"icon": "󰒓", "label": "Set up Zipline", "action": "omarchy-launch-floating-terminal-with-presentation " + shlex.quote(z + " setup")},
}
block = "  // " + begin + " (managed by omarchy-zipline; uninstall.sh removes this block)\n"
block += "".join("  %s: %s,\n" % (json.dumps(k), json.dumps(v, ensure_ascii=False)) for k, v in rows.items())
block += "  // " + end + "\n"

close = text.rstrip().rfind("}")
if close < 0:
    sys.exit("menu file has no closing brace")
head, tail = text[:close], text[close:]

# The previous entry needs a trailing comma unless the object is empty.
significant = [l for l in head.split("\n") if l.strip() and not l.strip().startswith("//")]
last = significant[-1].rstrip() if significant else "{"
if not last.endswith("{") and not last.endswith(","):
    idx = head.rfind(last)
    head = head[: idx + len(last)] + "," + head[idx + len(last):]

new = head.rstrip("\n") + "\n" + block + tail

# Same parsing the Omarchy menu does: strip full-line comments and trailing commas.
stripped = re.sub(r"^\s*//[^\n]*(\n|$)", "", new, flags=re.M)
stripped = re.sub(r",(\s*[}\]])", r"\1", stripped)
json.loads(stripped)
open(path, "w", encoding="utf-8").write(new)
PY
    say "Menu: Omarchy menu > Capture > Zipline"
  else
    say "Could not update $MENU_FILE safely; left it unchanged"
  fi
fi

# 6. Let Hyprland pick up the bindings and report config errors.
if ((WANT_BINDINGS)) && have hyprctl && [[ -n ${HYPRLAND_INSTANCE_SIGNATURE:-} ]]; then
  hyprctl reload >/dev/null 2>&1 || true
  errors=$(hyprctl configerrors 2>/dev/null | grep -v '^\s*$' || true)
  if [[ -n $errors && $errors != *"no errors"* ]]; then
    say "Hyprland reported config errors:"
    printf '%s\n' "$errors" | sed 's/^/      /'
  fi
fi

echo
if "$HELPER" server >/dev/null 2>&1; then
  echo "Done. Press Shift + Print to upload a screenshot."
else
  echo "Done. Next: run 'omarchy-zipline setup' (or Omarchy menu > Capture > Zipline > Set up)"
  echo "and paste your server URL and the API token from Zipline (avatar > Copy token)."
fi
